abstract class Document {
    public abstract Document cloneDocument();
}

class PdfDocument extends Document {
    @Override
    public PdfDocument cloneDocument() {
        // Covariant return type allows returning PdfDocument directly
        return new PdfDocument();
    }
}

public class Client {
    public static void main(String[] args) {
        PdfDocument pdf = new PdfDocument();
        // No cast required because of covariant return types
        PdfDocument clonedPdf = pdf.cloneDocument();
    }
}
